// Binary search over a sorted (nondecreasing) slice.
// Returns true iff k appears in a.
fn bin_search(a: &[i32], k: i32) -> bool {
    let mut lo: usize = 0;
    let mut hi: usize = a.len(); // search interval is [lo, hi)

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let v = a[mid];

        if v == k {
            return true;
        } else if v < k {
            lo = mid + 1; // discard [lo, mid]
        } else {
            hi = mid; // discard [mid, hi)
        }
    }

    false
}

